    "presnap": "npm run prepare",
    "test": "tap",
    "snap": "tap",
    "format": "prettier --write .",
    "benchmark": "node benchmark/index.js",
    "typedoc": "typedoc --tsconfig .tshy/esm.json ./src/*.ts"
  },
  "engines": {
    "node": "20 || >=22"
  },
  "devDependencies": {
    "@types/node": "^24.0.0",
